import { courtText, courtHtml, setCourtMode, isCourtMode } from './court-ui.js';
'use strict';
import { createAnalysis } from './analysis.js';
import { sortableTable, scoreRatio, installTableSorting } from './table-sort.js';
import { createPerformance } from './performance.js';
import { createCourt } from './zhanfan.js';

const TITLE = '断剑蘸饭审判法庭';
const READ_ONLY = !!window.COURT_READONLY;
const READ_ACTIONS = new Set(['close-modal','refresh','filter-days','clear-filters','prev-page','next-page','analytics-tab','detail-tab','battle-mode','performance-mode','back-matches','download-match','player-fields','unit-fields','friend-tab','analysis-map']);

const MODES = {0:'普通模式',1:'排位赛',2:'休闲赛',3:'遭遇战'};
const NAV = [['dashboard','layout-dashboard','法庭总览'],['matches','archive','对局档案'],['analytics','chart-no-axes-combined','开黑分析'],['members','users','朋友与账号'],['sync','database','数据管理']].filter(([key])=>!READ_ONLY||key!=='sync');
const S = { user:null, setup:false, registering:false, invite:'', members:[], maps:[], modes:[], sync:null, route:'dashboard', page:1, detailTab:'summary', analyticsTab:'members', filters:{days:'0',member:'',map:'',mode:'0',team:'',from:'',to:''}, scope:'qualified', query:'', currentMatch:null, selectedPlayer:'', unitSearch:'', compareA:'',compareB:'', version:0 };
Object.assign(S,{friendTab:"overview",analysisMin:5,currentFriend:null});
Object.assign(S,{performanceMode:'battle',comboMin:5,supplyMin:5});
S.courtMin=5;
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name) => `<i data-lucide="${name}" aria-hidden="true"></i>`;
const fmt = (n,d=0) => n===null||n===undefined||!Number.isFinite(Number(n))?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const compact = (n) => n===null||n===undefined?'—':Math.abs(n)>=10000?`${fmt(n/10000,1)}万`:fmt(n);
const pct = (a,b) => b?`${fmt(100*a/b,1)}%`:'—';
const ratio = (a,b) => a===null||a===undefined||b===null||b===undefined?'—':b?fmt(a/b,2):a>0?'∞':'—';
const delta = (n) => n===null||n===undefined?'—':`${n>0?'+':''}${fmt(n,1)}`;
const duration = (n) => n===null||n===undefined?'—':`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;
const time = (v,short=false) => !v?'—':new Date(typeof v==='number'?v*1000:v).toLocaleString('zh-CN',{timeZone:'Asia/Hong_Kong',month:'2-digit',day:'2-digit',...(short?{}:{year:'numeric'}),hour:'2-digit',minute:'2-digit',hour12:false});
const hours = (n) => `${fmt((n||0)/3600,1)} h`;
const mode = (v) => v===null||v===undefined?'未知模式':MODES[v] ?? `模式 ${esc(v)}`;
const signedClass = (n) => n>0?'positive':n<0?'negative':'muted';
const button = (label,action,ico='',cls='',attrs='') => READ_ONLY&&!READ_ACTIONS.has(action)?'':`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${esc(label)}</button>`;
const iconButton = (label,action,ico,attrs='') => READ_ONLY&&!READ_ACTIONS.has(action)?'':`<button type="button" class="icon-button" title="${esc(label)}" aria-label="${esc(label)}" data-action="${action}" ${attrs}>${icon(ico)}</button>`;
const badge = (text,cls='') => `<span class="badge ${cls}">${esc(text)}</span>`;
function accountSyncBadge(a) {
  if(READ_ONLY)return badge(`${fmt(a.archived_count)} 局开黑`,'muted');
  const note = a.last_error || (a.history_missing_count ? `近期同步正常；${a.history_missing_count} 条历史比赛数据上游暂未返回，已保留 ID 并定期复查。已归档数据不受影响。` : '');
  return `<span title="${esc(note)}">${badge(a.last_error?'同步异常':a.history_missing_count?'已同步 · 历史有缺失':a.last_profile_sync?'已同步':'待同步',a.last_error?'red':a.history_missing_count?'yellow':a.last_profile_sync?'':'muted')}</span>`;
}
const isAdmin = () => !READ_ONLY&&S.user?.role==='admin';
const canManage = (id) => !READ_ONLY&&(isAdmin() || S.user?.member_id===Number(id));
function icons() { window.lucide?.createIcons({attrs:{'aria-hidden':'true'}}); }
function toast(message,error=false) {
  const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;
  const host=$('#toasts');host.append(el);
  while(host.children.length>3)host.firstElementChild.remove();
  setTimeout(()=>el.remove(),5000);
}
async function api(route,{method='GET',body,blob=false}={}) {
  if(READ_ONLY)return window.COURT_READONLY_API.request(route,{method});
  const headers={}; if(body!==undefined) headers['Content-Type']='application/json';
  if(method!=='GET'&&S.user?.csrf)headers['X-CSRF-Token']=S.user.csrf;
  const response=await fetch(route,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});
  if(!response.ok){const data=await response.json().catch(()=>({}));if(response.status===401&&S.user){S.user=null;if($('#modal').open)closeModal();renderAuth();}throw new Error(data.error||`请求失败 (${response.status})`);}
  return blob?response.blob():response.json();
}
function params(extra={}) {const p=new URLSearchParams();for(const[k,v]of Object.entries({...S.filters,...extra})){if(v!==''&&v!==undefined&&v!==null&&v!=='custom')p.set(k,String(v));}return p;}
function heading(title,eyebrow,subtitle='',actions='') {return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function empty(title,description='',actions='',ico='archive',compact=false){return `<div class="empty ${compact?'compact':''}">${icon(ico)}<h3>${esc(title)}</h3>${description?`<p>${esc(description)}</p>`:''}${actions?`<div class="empty-actions">${actions}</div>`:''}</div>`;}
function kpi(label,value,foot,ico,cls=''){return `<div class="kpi"><div class="kpi-label">${icon(ico)}${esc(label)}</div><div class="kpi-value ${cls}">${value}</div><div class="kpi-foot">${esc(foot)}</div></div>`;}
function statKpis(data){const o=data.overview;return `<div class="kpis">${kpi(courtText('开黑对局'),fmt(o.matches),courtText('同局至少 3 位不同朋友'),'swords','yellow')}${kpi(courtText('参与朋友'),fmt(data.members.length),courtHtml`已登记 ${o.active_members} 位朋友`,'users')}${kpi(courtText('开黑时长'),`${fmt(o.duration/3600,1)}<small>小时</small>`,'每局时长仅计算一次','clock-3')}${kpi(courtText('完整归档'),`${fmt(o.complete)}<small>/ ${fmt(o.matches)}</small>`,'包含单位、经济与补给明细','database','positive')}</div>`;}
function filterBar({personal=false}={}){return `<div class="filters" aria-label="对局筛选"><div class="segmented">${[['0','全部'],['7','近 7 天'],['30','近 30 天'],['90','近 90 天'],['custom','日期范围']].map(([v,n])=>`<button class="${S.filters.days===v?'active':''}" data-action="filter-days" data-value="${v}" aria-pressed="${S.filters.days===v}">${n}</button>`).join('')}</div>${personal?'':courtHtml`<select data-filter="member" aria-label="参与朋友"><option value="">全部朋友</option>${S.members.map((m)=>`<option value="${m.id}" ${String(m.id)===S.filters.member?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`}<select data-filter="map" aria-label="地图"><option value="">全部地图</option>${S.maps.map((m)=>`<option value="${esc(m.map_id)}" ${m.map_id===S.filters.map?'selected':''}>${esc(m.name)}</option>`).join('')}</select><select data-filter="mode" aria-label="游戏模式"><option value="">全部模式</option>${[{mode:'0'},...S.modes.filter((m)=>m.mode!=='0')].map((m)=>`<option value="${esc(m.mode)}" ${m.mode===S.filters.mode?'selected':''}>${mode(m.mode)}</option>`).join('')}</select><select data-filter="team" aria-label="队伍条件"><option value="">同局 ≥ 3 人</option><option value="same" ${S.filters.team==='same'?'selected':''}>同队 ≥ 3 人</option></select>${S.filters.days==='custom'?`<input type="date" data-filter="from" aria-label="开始日期" value="${esc(S.filters.from)}"><span class="muted">至</span><input type="date" data-filter="to" aria-label="结束日期" value="${esc(S.filters.to)}">`:''}${iconButton('清除筛选','clear-filters','rotate-ccw')}</div>`;}
function shell(){const current=NAV.find(([key])=>key===S.route)?.[2]??(S.route==='friend'?courtText('朋友详细分析'):courtText('对局详情'));$('#app').innerHTML=courtHtml`<div class="layout"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-mark">${icon('scale')}</span><div><div class="brand-name">断剑蘸饭<br>审判法庭</div><small>BROKEN ARROW COURT</small></div></a><div class="nav-label">法庭档案</div><nav class="nav" aria-label="主导航">${NAV.map(([key,i,label])=>`<a href="#${key}" class="${(S.route===key||(S.route==='friend'&&key==='analytics'))?'active':''}" ${(S.route===key||(S.route==='friend'&&key==='analytics'))?'aria-current="page"':''}>${icon(isCourtMode()?({dashboard:"gavel",matches:"files",analytics:"scale",members:"fingerprint",sync:"notebook-pen"}[key]||i):i)}<span>${courtText(label)}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="sync-indicator" id="sidebar-sync"><span class="dot"></span><span class="muted">正在读取同步状态</span></div><div class="user-box"><span class="avatar">${esc(S.user.name.slice(0,1))}</span><div class="grow"><div class="truncate small-text">${esc(S.user.name)}</div><div class="faint" style="font-size:10px">${READ_ONLY?courtText('只读访客'):isAdmin()?courtText('管理员'):courtText('朋友')}</div></div>${iconButton('账号设置','password','settings-2')}${iconButton('退出登录','logout','log-out')}</div></div></aside><div class="main-shell"><header class="topbar"><span class="topbar-path"><span class="desktop-only">法庭 / </span><span class="brand-short">${esc(courtText(current))}</span><span class="mobile-brand">${TITLE}</span></span><div class="topbar-right">${isAdmin()?button(isCourtMode()?"休庭":"开庭","toggle-court-mode","gavel","court-toggle",`aria-pressed="${isCourtMode()}"`):""}<span class="rule-badge">${icon('users-round')}同局 ≥ 3 位朋友</span><span class="${READ_ONLY?'snapshot-time':'muted'}">${READ_ONLY?`数据更新 ${time(window.COURT_READONLY_API.metadata?.published_at,true)}`:'UTC+8'}</span>${iconButton('刷新当前页面','refresh','refresh-cw')}${READ_ONLY?'':`<button class="icon-button mobile-account" title="账号设置" aria-label="账号设置" data-action="password">${icon('user-round')}</button>`}</div></header>${courtSessionBanner()}<main class="main" id="main"><div class="loading-page"><span class="spinner"></span></div></main></div></div>`;icons();updateSyncIndicator();}
function renderAuth(){const register=S.setup||S.registering;$('#app').innerHTML=courtHtml`<main class="auth-page"><div class="auth-brand"><span class="brand-mark">${icon('scale')}</span><span>${TITLE}</span></div><section class="auth-content"><div class="eyebrow">BROKEN ARROW / PRIVATE ARCHIVE</div><h1>${S.setup?'法庭开庭':register?courtText('加入朋友的法庭'):'欢迎回到法庭'}</h1><p class="auth-sub">${S.setup?courtText('创建首位管理员'):register?courtText('使用朋友的邀请码注册'):'登录你的法庭账号'}</p><form id="auth-form"><input type="hidden" name="register" value="${register}">${register?courtHtml`<label>朋友称呼<input name="name" required maxlength="40" autocomplete="nickname" placeholder="大家怎么称呼你"></label>`:''}<label>登录名<input name="username" required minlength="3" maxlength="64" pattern="[a-zA-Z0-9_.@-]{3,64}" autocomplete="username" placeholder="字母、数字或 _.@-"></label><label>密码<input name="password" type="password" required ${register?'minlength="10"':''} maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'至少 10 个字符':'你的密码'}"></label>${register?`<label>确认密码<input name="confirm" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label>`:''}${register&&!S.setup?`<label>邀请码<input name="invite" required value="${esc(S.invite)}" autocomplete="off"></label>`:''}<div class="form-error" id="auth-error" role="alert"></div><button class="primary" type="submit">${icon(S.setup?'gavel':register?'user-plus':'log-in')}${S.setup?'创建法庭':register?'注册并加入':'登录'}</button></form>${!S.setup?`<div class="auth-switch">${register?'已经有账号？':courtText('收到朋友的邀请？')}<button data-action="toggle-auth">${register?'返回登录':'注册账号'}</button></div>`:''}<div class="auth-rule">${icon('users-round')}同局至少三位朋友，才进入法庭统计。</div></section><div class="auth-footer">${TITLE} · 私人对局档案</div></main>`;icons();}
async function init(){try{const session=await api('/api/session');S.user=session.user;S.setup=session.setup_required;setCourtMode(session.ui?.court_mode===true);if(location.hash.startsWith('#join/')){S.invite=decodeURIComponent(location.hash.slice(6));S.registering=true;}if(!S.user){renderAuth();return;}await route();}catch(e){$('#app').innerHTML=`<div class="error-page">${esc(e.message)}</div>`;}}
async function route({quiet=false}={}) {
  if(!S.user)return renderAuth();
  const hash=location.hash.slice(1)||'dashboard',next=hash.split('/')[0];
  S.route=NAV.some(([key])=>key===next)||['match','friend'].includes(next)?next:'dashboard';
  if(!quiet||!$('#main'))shell();const version=++S.version;
  try {
    const [members,maps,sync]=await Promise.all([api('/api/members'),api('/api/maps'),api('/api/sync/status')]);
    if(version!==S.version)return;S.members=members.members;S.maps=maps.maps;S.modes=maps.modes;S.sync=sync;if(setCourtMode(sync.settings.court_mode===true))shell();
    if(S.route==='dashboard'){
      const data=await api(`/api/dashboard?${params()}`),recent=await api(`/api/matches?${params({page:1})}`);if(version!==S.version)return;$('#main').innerHTML=dashboardView(data,recent);drawActivity(data.daily);
    }else if(S.route==='matches'){
      const data=await api(`/api/matches?${params({page:S.page,q:S.query,scope:S.scope==='all'?'all':null})}`);if(version!==S.version)return;$('#main').innerHTML=matchesView(data);
    }else if(S.route==='members')$('#main').innerHTML=membersView();
    else if(S.route==='analytics'){
      const data=await api(`/api/dashboard?${params({combo_min_games:S.comboMin})}`);
      const deep=S.analyticsTab==='court'?await api(`/api/analytics/zhanfan?${params({court_min_games:S.courtMin})}`):S.analyticsTab==='supply'?await api(`/api/analytics/supply?${params({supply_min_games:S.supplyMin})}`):['decks','maps','units'].includes(S.analyticsTab)?await api(`/api/analytics/overview?${params({min_games:S.analysisMin})}`):null;
      if(version!==S.version)return;$('#main').innerHTML=analyticsView(data,deep);
    }else if(S.route==='friend'){
      const id=hash.split('/')[1];if(!/^\d+$/.test(id??''))throw new Error(courtText('无效的朋友 ID'));
      const data=await api(`/api/members/${id}/analysis?${params({member:id,min_games:S.analysisMin,court_min_games:S.courtMin})}`);if(version!==S.version)return;$('#main').innerHTML=friendView(data);
    }else if(S.route==='sync')$('#main').innerHTML=syncView();
    else if(S.route==='match'){
      const id=hash.split('/')[1];if(!/^\d+$/.test(id??''))throw new Error('无效的对局 ID');const data=await api(`/api/matches/${id}`);if(version!==S.version)return;S.currentMatch=data;$('#main').innerHTML=detailView(data);
    }
    icons();updateSyncIndicator();
  }catch(e){if(version===S.version&&$('#main'))$('#main').innerHTML=`<div class="error-page">${icon('triangle-alert')}<p>${esc(e.message)}</p><div class="empty-actions">${button('重试','refresh','refresh-cw')}</div></div>`;icons();}
}
function dashboardView(data,recent){const o=data.overview;return heading(courtText('法庭总览'),'THE COURT / OVERVIEW',o.latest?`${time(o.earliest)} 至 ${time(o.latest)}`:courtText('对局档案等待入席'),button(courtText('登记游戏账号'),'add-account','plus','primary')+(isAdmin()?button(courtText('立即同步'),'sync-now','refresh-cw'):''))+filterBar()+statKpis(data)+(!S.members.some((m)=>m.accounts.length)?empty(READ_ONLY?'暂无公开开黑档案':'第一份战绩，等待入档',READ_ONLY?'等待下一次数据更新。':courtText('先登记你和朋友的游戏账号。'),button(courtText('登记游戏账号'),'add-account','plus','primary')+(isAdmin()?button(courtText('添加朋友'),'add-member','user-plus'):''),'swords'):courtHtml`<div class="two-columns"><section><div class="section-heading"><h2>开黑活动</h2><small>按香港时间归档</small></div><div class="chart-wrap">${data.daily.length?courtText('<canvas id="activity-chart" class="chart" aria-label="每日开黑对局数量"></canvas>'):'<div class="chart-empty">当前筛选下暂无开黑记录</div>'}</div></section><section><div class="section-heading"><h2>地图分布</h2><small>${fmt(o.matches)} 局</small></div>${mapList(data.maps)}</section></div><section class="section-space"><div class="section-heading"><h2>最近的开黑</h2><a class="small-text muted" href="#matches">全部对局 →</a></div>${recent.items.length?matchTable(recent.items.slice(0,5)):empty('暂无符合条件的对局',courtText('已归档的候选记录将在朋友达到三位后自动纳入。'),'','archive',true)}</section><section class="section-space"><div class="section-heading"><h2>朋友表现</h2><small>仅计入符合三人规则的对局</small></div>${memberTable(data.members)}</section>`);}
function mapList(maps){if(!maps.length)return empty('暂无地图记录','','','map',true);const max=Math.max(...maps.map((m)=>m.matches),1);return `<div class="map-list">${maps.slice(0,7).map((m)=>`<div class="map-row"><span class="map-name" title="${esc(m.name)}">${esc(m.name)}</span><div class="track"><span style="width:${100*m.matches/max}%"></span></div><span class="mono numeric">${m.matches}<span class="faint"> 局</span></span></div>`).join('')}</div>`;}
function matchTable(items){return courtHtml`<div class="table-wrap"><table><thead><tr><th>对局 / 地图</th><th>结束时间</th><th>模式 / 时长</th><th>入席朋友</th><th class="numeric">朋友人均摧毁 / 损失</th><th class="numeric">评分合计变化</th><th>档案</th><th></th></tr></thead><tbody>${items.map((m)=>courtHtml`<tr><td><a href="#match/${m.id}" class="table-title">${esc(m.map_name)}</a><div class="table-sub mono">#${m.id}</div></td><td class="nowrap">${time(m.end_time,true)}</td><td><div>${mode(m.mode)}</div><div class="table-sub mono">${duration(m.duration)}</div></td><td><div class="friend-chips">${m.friends.map((f)=>`<span class="friend-chip team-${f.team_id}" title="${esc(f.member_name)} · ${f.won===null?'胜负未知':f.won?'胜利':'失败'}">${esc(f.member_name)}</span>`).join('')}</div><div class="table-sub">${m.friend_count} 位朋友${m.same_team_count>=3?' · 同队 ≥ 3':' · 分处两队'}</div></td><td class="numeric mono"><span class="positive">${fmt(m.totals.avg_destruction,1)}</span><span class="faint"> / </span>${fmt(m.totals.avg_losses,1)}</td><td class="numeric mono ${signedClass(m.totals.rating_delta)}">${delta(m.totals.rating_delta)}</td><td>${badge(m.detail_state==='complete'?courtText('完整归档'):m.detail_state==='error'?'待重试':'待补详情',m.detail_state==='complete'?'':m.detail_state==='error'?'red':'muted')}</td><td><a href="#match/${m.id}" aria-label="查看对局 ${m.id}">${icon('arrow-up-right')}</a></td></tr>`).join('')}</tbody></table></div>`;}
function matchesView(data){return heading(courtText('对局档案'),'MATCH ARCHIVE',`${fmt(data.total)} 局 · 每页 20 局`,isAdmin()?button(courtText('导入档案'),'import','upload'):'' )+filterBar()+`<div class="section-heading"><form id="match-search" class="flex"><input name="q" value="${esc(S.query)}" placeholder="对局 ID / 玩家名称" aria-label="搜索对局" style="max-width:245px"><button type="submit" class="icon-button" title="搜索" aria-label="搜索">${icon('search')}</button></form>${isAdmin()?`<label class="inline-check"><input id="candidate-toggle" type="checkbox" ${S.scope==='all'?'checked':''}>包含候选记录</label>`:''}</div>`+(S.scope==='all'?`<div class="notice">${icon('filter')}候选库包含尚未满足三人条件的比赛，开黑统计仍只计算合格对局。</div>`:'')+(data.items.length?matchTable(data.items):empty('没有找到符合条件的对局',S.query?'尝试其他对局 ID 或玩家名称。':courtText('等待同步，或调整日期及朋友筛选。')))+`<div class="pagination"><span>${fmt(data.total)} 局</span><div class="flex">${iconButton('上一页','prev-page','chevron-left',data.page<=1?'disabled':'')}<span class="mono">${data.page} / ${data.pages}</span>${iconButton('下一页','next-page','chevron-right',data.page>=data.pages?'disabled':'')}</div></div>`;}
function memberTable(members){if(!members.length)return empty(courtText('暂无可统计的朋友战绩'),'','','users',true);if(S.performanceMode!=='battle')return performanceTabs()+detailPerformance(members);return performanceTabs()+sortableTable('friends',courtHtml`<div class="table-wrap"><table><thead><tr><th>朋友</th><th class="numeric">开黑局数</th><th class="numeric">胜率</th><th class="numeric">评分变化</th><th class="numeric">场均摧毁分</th><th class="numeric">场均损失分</th><th class="numeric">分数交换比</th><th class="numeric">场均占点</th><th class="numeric">场均友伤</th></tr></thead><tbody>${members.map((m)=>courtHtml`<tr><td class="table-title"><a href="#friend/${m.member_id}" class="friend-report-link">${esc(m.name)}<span class="table-sub">查看详细分析 →</span></a></td><td class="numeric mono">${fmt(m.matches)}</td><td class="numeric mono">${pct(m.wins,m.decided)}<div class="table-sub">${fmt(m.wins||0)} 胜 / ${fmt(m.losses_count||0)} 负</div></td><td class="numeric mono ${signedClass(m.rating_delta)}">${delta(m.rating_delta)}</td><td class="numeric mono positive">${fmt(m.avg_destruction,1)}</td><td class="numeric mono">${fmt(m.avg_losses,1)}</td><td class="numeric mono">${ratio(m.destruction,m.losses)}</td><td class="numeric mono">${fmt(m.avg_objectives,2)}</td><td class="numeric mono ${m.avg_friendly_fire>0?'negative':'muted'}" title="${m.friendly_fire_matches} / ${m.matches} 局有完整友伤数据">${fmt(m.avg_friendly_fire,2)}<div class="table-sub">${fmt(m.friendly_fire_matches)} 局样本</div></td></tr>`).join('')}</tbody></table></div>`,members,[
{index:0,key:'name',label:courtText('朋友'),type:'text',value:r=>r.name},
{index:1,key:'matches',label:'开黑局数',value:r=>r.matches},
{index:2,key:'win_rate',label:'胜率',value:r=>r.decided?r.wins/r.decided:null},
{index:3,key:'rating_delta',label:'评分变化',value:r=>r.rating_delta},
{index:4,key:'destruction',label:'场均摧毁分',value:r=>r.avg_destruction},
{index:5,key:'losses',label:'场均损失分',value:r=>r.avg_losses,first:'asc'},
{index:6,key:'exchange',label:'分数交换比',value:r=>scoreRatio(r.destruction,r.losses)},
{index:7,key:'objectives',label:'场均占点',value:r=>r.avg_objectives},
{index:8,key:'friendly_fire',label:'场均友伤',value:r=>r.avg_friendly_fire,first:'asc'}]);}
function comboTable(combos){if(!combos.length)return empty(courtText('暂无同队搭档记录'),'','','handshake',true);return sortableTable('combos',courtHtml`<div class="table-wrap"><table><thead><tr><th>同队搭档</th><th class="numeric">共同开黑</th><th class="numeric">胜率</th><th class="numeric">胜场</th><th class="numeric">已知结果</th></tr></thead><tbody>${combos.map((c)=>`<tr><td>${esc(c.name_a)}<span class="faint"> + </span>${esc(c.name_b)}</td><td class="numeric mono">${fmt(c.matches)}</td><td class="numeric mono ${c.decided>=10?'positive':'muted'}">${pct(c.wins,c.decided)}</td><td class="numeric mono">${fmt(c.wins||0)}</td><td class="numeric mono">${fmt(c.decided)}</td></tr>`).join('')}</tbody></table></div>`,combos,[
{index:0,key:'name',label:courtText('同队搭档'),type:'text',value:r=>r.name_a+' + '+r.name_b},
{index:1,key:'matches',label:courtText('共同开黑'),value:r=>r.matches},
{index:2,key:'win_rate',label:'胜率',value:r=>r.decided?r.wins/r.decided:null},
{index:3,key:'wins',label:'胜场',value:r=>r.wins},
{index:4,key:'decided',label:'已知结果',value:r=>r.decided}]);}
function analyticsView(data,deep) {
  const tabs=[['members',courtText('朋友表现')],['court','蘸饭指数榜'],['combos',courtText('同队搭档')],['supply','补给分析'],['decks','专精组合'],['maps','地图胜率'],['units','单位表现']];
  return heading(courtText('开黑分析'),'FRIENDS / ANALYTICS',courtText('多账号合并到同一位朋友；点击朋友姓名查看详细分析。'))+filterBar()+`<div class="tabs analysis-tabs">${tabs.map(([v,n])=>`<button data-action="analytics-tab" data-value="${v}" class="${S.analyticsTab===v?'active':''}">${n}</button>`).join('')}</div>`+
    (deep?S.analyticsTab==='court'?courtView(deep):S.analyticsTab==='supply'?supplyView(deep):deepAnalytics(deep):S.analyticsTab==='members'?memberTable(data.members)+courtHtml`<div class="notice section-space">${icon('info')}按场均展示；同一朋友同局多账号先合并。详情指标不以缺失场次充零；分数交换比使用累计摧毁分 / 累计损失分。</div>`:courtHtml`<div class="analysis-controls"><label>同队搭档最低局数<input id="combo-min" type="number" min="1" max="10000" step="1" value="${data.combo_min_games}"></label><span class="hint">${data.combos.length} 组搭档达到门槛</span></div>`+comboTable(data.combos)+courtHtml`<div class="notice section-space">${icon('info')}仅计算合格开黑局中的同队搭档，少于 ${data.combo_min_games} 局的组合不显示。胜率仅以结果已知的场次为分母。</div>`);
}
function localized(v){if(typeof v==='string')return v;if(v&&typeof v==='object')return v['zh-CN']??v.zh??v.en??Object.values(v).find((x)=>typeof x==='string')??'';return '';}
function unitName(catalogue,id){return localized(catalogue?.hudName)||localized(catalogue?.uiName)||localized(catalogue?.name)||`单位 #${id}`;}
function unitTable(units){if(!units?.length)return empty('暂无单位明细','合格对局完成详情归档后，单位表现将出现在这里。','','crosshair');return sortableTable('unit-details',`<div class="table-wrap"><table><thead><tr><th>单位</th><th class="numeric">实例 / 对局</th><th class="numeric">击杀</th><th class="numeric">造成伤害</th><th class="numeric">承受伤害</th><th class="numeric">平均伤害</th><th class="numeric">阵亡</th><th class="numeric">退款</th><th class="numeric">消耗补给</th></tr></thead><tbody>${units.map((u)=>`<tr><td class="table-title">${esc(unitName(u.catalogue,u.unit_id))}<div class="table-sub mono">#${u.unit_id}</div></td><td class="numeric mono">${fmt(u.instances)} / ${fmt(u.matches)}</td><td class="numeric mono">${fmt(u.kills)}</td><td class="numeric mono positive">${fmt(u.damage,1)}</td><td class="numeric mono">${fmt(u.damage_received,1)}</td><td class="numeric mono">${fmt(u.damage/u.instances,1)}</td><td class="numeric mono">${fmt(u.deaths)}</td><td class="numeric mono">${fmt(u.refunded)}</td><td class="numeric mono">${fmt(u.supply)}</td></tr>`).join('')}</tbody></table></div>`,units,[
{index:0,key:'name',label:'单位',type:'text',value:r=>unitName(r.catalogue,r.unit_id)},
{index:1,key:'instances',label:'实例 / 对局',value:r=>r.instances},
{index:2,key:'kills',label:'击杀',value:r=>r.kills},
{index:3,key:'damage',label:'造成伤害',value:r=>r.damage},
{index:4,key:'damage_received',label:'承受伤害',value:r=>r.damage_received},
{index:5,key:'average_damage',label:'平均伤害',value:r=>r.instances?r.damage/r.instances:null},
{index:6,key:'deaths',label:'阵亡',value:r=>r.deaths,first:'asc'},
{index:7,key:'refunded',label:'退款',value:r=>r.refunded},
{index:8,key:'supply',label:'消耗补给',value:r=>r.supply}]);}
function membersView(){return heading(courtText('朋友与账号'),'PEOPLE / ACCOUNTS',courtHtml`${S.members.filter((m)=>m.active).length} 位朋友 · ${S.members.reduce((n,m)=>n+m.accounts.length,0)} 个游戏账号`,button(courtText('登记账号'),'add-account','plus','primary')+(isAdmin()?button(courtText('添加朋友'),'add-member','user-plus')+button(courtText('邀请注册'),'invite','send'):''))+S.members.map((m)=>courtHtml`<section class="member-section ${m.active?'':'inactive'}"><div class="member-heading"><span class="avatar large">${esc(m.name.slice(0,1))}</span><div class="grow"><h2><a href="#friend/${m.id}">${esc(m.name)}</a> ${m.id===S.user.member_id?badge('我','muted'):''}</h2><small>${READ_ONLY?'参与开黑统计':m.username?`${esc(m.username)} · ${m.role==='admin'?courtText('管理员'):'已注册'}`:'已登记 · 尚未创建登录账号'}</small></div><div class="page-actions"><a class="report-link" href="#friend/${m.id}">详细分析</a>${canManage(m.id)?iconButton(courtText('修改称呼'),'edit-member','pencil',`data-id="${m.id}"`):''}${isAdmin()&&m.user_id&&m.id!==S.user.member_id?iconButton('重置登录密码','reset-password','key-round',`data-id="${m.user_id}"`):''}${isAdmin()&&!m.user_id&&m.active?iconButton(courtText('邀请该朋友认领登录账号'),'invite','send',`data-id="${m.id}"`):''}${isAdmin()&&m.id!==S.user.member_id?`<label class="switch" title="${m.active?courtText('停用朋友'):courtText('恢复朋友')}"><input type="checkbox" data-member-active="${m.id}" aria-label="启用 ${esc(m.name)}" ${m.active?'checked':''}><span></span></label>`:''}</div></div><div class="member-content"><div class="member-meta"><span>${m.accounts.length} 个账号</span><span>${m.accounts.filter((a)=>a.active).length} 个参与统计</span>${canManage(m.id)&&m.active?courtHtml`<a href="#" data-action="add-account" data-id="${m.id}" class="yellow">+ 登记账号</a>`:''}</div>${m.accounts.length?m.accounts.map((a)=>`<div class="account-row"><div class="account-name"><div class="truncate table-title">${esc(a.name)}</div><div class="table-sub mono">BA #${a.player_id}${a.steam_id?` · ${esc(a.steam_id)}`:''}</div></div><div class="account-id small-text muted">${fmt(a.archived_count)} 局已归档</div>${accountSyncBadge(a)}<div class="account-actions flex">${iconButton(courtText('查看账号生涯'),'profile','chart-column',`data-id="${a.id}"`)}${isAdmin()?iconButton(courtText('调整朋友归属'),'reassign','arrow-right-left',`data-id="${a.id}"`):''}${canManage(m.id)?`<label class="switch" title="${a.active?'停止跟踪':'恢复跟踪'}"><input type="checkbox" data-account-active="${a.id}" aria-label="跟踪 ${esc(a.name)}" ${a.active?'checked':''}><span></span></label>`:''}</div></div>`).join(''):courtHtml`<div class="muted small-text">尚未登记游戏账号</div>`}</div></section>`).join('');}
const PHASES={accounts:'读取账号',recent:'同步近期对局',backfill:'回溯历史',details:'补抓单场详情',units:'补齐单位资料'};
const RUN_STATES={running:'进行中',complete:'完成',partial:'部分完成',failed:'失败',paused:'已暂停',interrupted:'重启后待续'};
function courtSessionBanner(){
  if(!isCourtMode())return '';
  return '<div class="court-session" aria-label="正在开庭"><div class="court-session-mark" aria-hidden="true">'+icon('scale')+'</div><div class="court-session-copy"><span class="court-session-kicker">BROKEN ARROW · COURT IN SESSION</span><strong>现在开庭</strong><p>以卷宗为据，凭数据说话。</p></div><div class="court-session-seal" aria-hidden="true">蘸饭<br>法庭</div><span class="court-session-status"><span class="dot on"></span>正在审理</span></div>';
}
function courtModePanel(){
  return '<section class="court-mode-panel" aria-labelledby="court-mode-title"><div class="court-mode-icon">'+icon('gavel')+'</div><div class="grow"><h2 id="court-mode-title">开庭模式</h2><p>切换法庭主题与界面称呼。由本地服务端统一控制，公开网页随下一次发布更新。</p><small>开启：审判大厅 · 对局卷宗 · 庭审分析 · 看守所 · 书记官室</small></div><div class="court-mode-action">'+badge(isCourtMode()?'正在开庭':'常规界面',isCourtMode()?'yellow':'muted')+(isAdmin()?button(isCourtMode()?'休庭，恢复常规界面':'开庭，启用法庭界面','toggle-court-mode','gavel','primary'):badge('仅管理员可切换','muted'))+'</div></section>';
}
function syncView(){const s=S.sync;const admin=isAdmin();return heading(courtText('数据管理'),'DATA / OPERATIONS',`最近同步完成：${time(s.settings.last_sync_finished)}`,admin?button(courtText('立即同步'),'sync-now','refresh-cw','primary')+button(courtText('全量回溯'),'sync-full','history')+button(courtText('按 ID 补抓'),'fetch-match','search')+button(courtText('导入'),'import','upload'):'' )+courtModePanel()+`<div class="kpis">${kpi(courtText('候选对局'),fmt(s.stats.candidates),courtText('已保存的全部对局'),'archive')}${kpi(courtText('合格开黑'),fmt(s.stats.qualified),courtText('至少三位朋友参与'),'users','yellow')}${kpi(courtText('完整详情'),fmt(s.stats.complete),`${s.stats.detail_errors} 局等待重试`,'file-check-2','positive')}${kpi('单位实例',fmt(s.stats.units),`${fmt(s.stats.database_bytes/1048576,1)} MB 数据库`,'crosshair')}</div>`+(s.active?`<div class="sync-live"><span class="spinner"></span><div class="grow"><strong>${PHASES[s.active.phase]||'同步中'}</strong><div class="muted">${esc(s.active.account||(s.active.match?courtHtml`对局 #${s.active.match}`:'后台运行中'))} · ${s.active.requests} 次请求 · 新增 ${s.active.imported} 局</div></div>${s.queued?badge('另有任务排队','yellow'):''}</div>`:'')+(s.blocked_until?`<div class="notice error">${icon('timer')}数据源冷却至 ${time(s.blocked_until)}，随后自动重试。</div>`:'')+courtHtml`<form id="sync-settings" class="settings-strip"><label class="inline-check"><span class="switch"><input name="enabled" type="checkbox" ${s.settings.sync_enabled?'checked':''} ${!admin?'disabled':''}><span></span></span>持续同步</label><label>同步间隔（分钟）<input name="minutes" type="number" min="5" max="1440" step="1" value="${s.settings.sync_minutes}" ${!admin?'disabled':''}></label><label>请求间隔（毫秒）<input name="delay" type="number" min="1000" max="60000" step="100" value="${s.settings.request_delay_ms}" ${!admin?'disabled':''}></label>${admin?'<button type="submit">'+icon('check')+'保存设置</button>':''}</form><section><div class="section-heading"><h2>历史覆盖</h2><small>按每个账号分别回溯</small></div>${s.accounts.length?courtHtml`<div class="table-wrap"><table><thead><tr><th>朋友 / 账号</th><th class="numeric">本地归档</th><th class="numeric">上游当前可查</th><th>回溯进度</th><th>最近同步</th><th>状态</th></tr></thead><tbody>${s.accounts.map((a)=>`<tr><td>${esc(a.member_name)}<div class="table-sub">${esc(a.name)} · #${a.player_id}</div></td><td class="numeric mono">${fmt(a.archived_count)}</td><td class="numeric mono">${fmt(a.backfill_total)}</td><td style="min-width:130px"><span class="small-text muted">${a.history_complete?(a.history_missing_count?`历史索引已扫描 · ${a.history_missing_count} 条暂缺`:'当前可查历史已完成'):`${fmt(a.backfill_offset)} / ${fmt(a.backfill_total)}`}</span><div class="progress"><span style="width:${a.history_complete?100:a.backfill_total?Math.min(100,100*a.backfill_offset/a.backfill_total):0}%"></span></div></td><td class="nowrap">${time(a.last_recent_sync,true)}</td><td title="${esc(a.last_error||(a.history_missing_count?`${a.history_missing_count} 条历史比赛数据上游暂未返回，已保留 ID 并定期复查。`:''))}">${badge(!a.active?'已停用':a.last_error?'待重试':a.history_missing_count?'历史有缺失':a.history_complete?'持续跟踪':'回溯中',!a.active?'muted':a.last_error?'red':a.history_missing_count?'yellow':a.history_complete?'':'yellow')}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无跟踪账号','',button(courtText('登记账号'),'add-account','plus'),'users',true)}</section><div class="notice section-space">${icon('info')}上游数量可能包含已无法返回数据的历史 ID；历史索引扫描完成不代表每局数据齐全。暂缺 ID 会保留并定期复查，已归档对局不会删除。</div><section class="section-space"><div class="section-heading"><h2>同步日志</h2><small>${s.events.length} 条最近事件</small></div>${eventLog(s.events)}</section><section class="section-space"><div class="section-heading"><h2>同步任务</h2></div>${s.runs.length?`<div class="table-wrap"><table><thead><tr><th>开始时间</th><th>类型</th><th>状态</th><th class="numeric">请求</th><th class="numeric">新增</th><th class="numeric">更新</th><th class="numeric">错误</th></tr></thead><tbody>${s.runs.slice(0,10).map((r)=>`<tr><td class="nowrap">${time(r.started_at)}</td><td>${r.kind==='full'?courtText('全量回溯'):'增量同步'}</td><td>${badge(RUN_STATES[r.status]||r.status,r.errors?'yellow':r.status==='complete'?'':'muted')}</td><td class="numeric mono">${r.requests}</td><td class="numeric mono positive">${r.imported}</td><td class="numeric mono">${r.changed}</td><td class="numeric mono ${r.errors?'negative':''}">${r.errors}</td></tr>`).join('')}</tbody></table></div>`:empty(courtText('暂无同步任务'),'','','history',true)}</section>${admin?courtHtml`<section class="section-space"><div class="section-heading"><h2>备份与导出</h2><small>最近备份：${time(s.settings.last_backup)}</small></div><div class="flex wrap">${button(courtText('数据库备份'),'backup','database-backup')}${button(courtText('导出完整档案'),'export','download')}</div><p class="hint" style="margin-top:12px">数据库备份包含用户、账号归属和全部档案。JSON 导出包含对局与生涯数据，不包含登录凭据。</p></section>`:''}`;}
function eventLog(events){return events.length?`<div class="log">${events.map((e)=>`<div class="log-row ${e.level}"><time>${time(e.created_at)}</time><span class="log-level">${{info:'信息',warning:'注意',error:'错误'}[e.level]||e.level}</span><span class="log-message">${esc(e.message)}</span></div>`).join('')}</div>`:empty('暂无日志','','','list',true);}
function updateSyncIndicator(){if(READ_ONLY){const el=$('#sidebar-sync');if(el)el.innerHTML=`<span class="dot on"></span><span class="muted">${S.updateAvailable?'有新数据，点击刷新加载':`数据更新 ${time(window.COURT_READONLY_API.metadata?.published_at,true)}`}</span>`;return;}const s=S.sync;const el=$('#sidebar-sync');if(!el||!s)return;const busy=!!s.active;const enabled=s.settings.sync_enabled;el.innerHTML=`<span class="dot ${busy?'busy':enabled?'on':''}"></span><span class="${busy?'yellow':'muted'}">${busy?'后台同步中':enabled?`每 ${s.settings.sync_minutes} 分钟同步`:'自动同步已暂停'}</span>`;}

function detailView(m){const winner=m.winner_team===null?'结果未知':`队伍 ${m.winner_team===0?'A':m.winner_team===1?'B':m.winner_team} 获胜`;return heading(courtHtml`对局 #${m.id}`,'CASE FILE / MATCH',`${m.map_name} · ${time(m.end_time)} · ${duration(m.duration)}`,button('返回档案','back-matches','arrow-left')+button(courtText('下载原始档案'),'download-match','download')+(isAdmin()&&m.friend_count>=3?button('补抓详情','retry-detail','refresh-cw'):''))+`<div class="flex wrap">${badge(courtHtml`${m.friend_count} 位朋友`,m.friend_count>=3?'yellow':'muted')}${badge(m.friend_count>=3?'已纳入法庭':'候选记录',m.friend_count>=3?'':'muted')}${badge(m.detail_state==='complete'?courtText('完整详情'):courtText('赛后汇总'),m.detail_state==='complete'?'':'muted')}<span class="small-text muted">${mode(m.mode)} · ${winner}</span></div><div class="detail-meta"><span>胜利等级 ${esc(m.victory_level??'—')}</span><span>玩家 ${m.participants.length} 人</span><span>单位 ${m.units.length} 个实例</span><a href="https://dash.batrace.top/match/${m.id}" target="_blank" rel="noopener noreferrer" class="cyan">BATrace 原始页面 ↗</a></div>${m.detail_error?`<div class="notice error section-space">${icon('triangle-alert')}${esc(m.detail_error)}</div>`:''}<div class="tabs">${[['summary',courtText('赛后统计')],['units',courtText('单位与时间轴')],['compare',courtText('玩家对比')],['raw',courtText('原始档案')]].map(([v,n])=>`<button data-action="detail-tab" data-value="${v}" class="${S.detailTab===v?'active':''}">${n}</button>`).join('')}</div><div id="detail-content">${detailContent(m)}</div>`;}
const RAW_COLUMNS={battle:[['destruction','摧毁分'],['losses','损失分'],['DamageDealt','伤害'],['DamageReceived','承伤'],['DamageFriendlyFireDealt','友伤'],['objectives','占点'],['TotalExp','经验']],economy:[['TotalSpawnedUnitScore','出场分数'],['TotalRefundedUnitScore','退款分数'],['Destruction','击毁数量'],['Losses','损失数量'],['TotalExp','经验'],['RawExp','原始经验']],supply:[['SupplyPointsConsumed','消耗补给'],['SupplyPointsConsumedByAllies','补给队友'],['SupplyPointsConsumedFromAllies','从队友补给'],['SupplyCaptured','占领补给'],['SupplyCapturedByEnemy','被敌占补给'],['DamageFriendlyFireReceived','承受友伤']]};
S.battleMode='battle';
function playerValue(p,key,m){return key in p?p[key]:p.raw[key]??(m.detail_state==='complete'?0:null);}
function detailContent(m){if(S.detailTab==='units')return timelineView(m);if(S.detailTab==='compare')return compareView(m);if(S.detailTab==='raw')return `<div class="section-heading"><h2>原始数据</h2><small>保留源字段与未识别字段</small></div>${jsonTree({summary:m.raw,detail:m.detail})}`;return `<div class="section-heading"><h2>团队战绩</h2><div class="segmented">${[['battle','战斗'],['economy','经济'],['supply','补给']].map(([v,n])=>`<button data-action="battle-mode" data-value="${v}" class="${S.battleMode===v?'active':''}">${n}</button>`).join('')}</div></div>${[...new Set(m.participants.map((p)=>p.team_id))].sort((a,b)=>a-b).map((team)=>{const players=m.participants.filter((p)=>p.team_id===team);return `<section style="margin-bottom:22px"><div class="team-heading team-${team}"><span class="dot"></span><h3>${team===100?'观战者':`队伍 ${team===0?'A':team===1?'B':team??'未知'}`}</h3>${team===m.winner_team?badge('胜利'):''}</div><div class="table-wrap"><table class="battle-table"><thead><tr><th>玩家</th><th class="numeric">评分变化</th><th class="numeric">分数交换比</th>${RAW_COLUMNS[S.battleMode].map(([,n])=>`<th class="numeric">${n}</th>`).join('')}<th></th></tr></thead><tbody>${players.map((p)=>`<tr><td><span class="${p.registered?'registered-name':'table-title'}">${esc(p.name)}</span>${p.registered?`<span class="player-chip">${esc(p.member_name)}</span>`:''}<div class="table-sub mono">#${p.player_id}</div>${participantDeck(p)}</td><td class="numeric mono ${signedClass(p.rating_delta)}">${delta(p.rating_delta)}</td><td class="numeric mono">${ratio(p.destruction,p.losses)}</td>${RAW_COLUMNS[S.battleMode].map(([key])=>`<td class="numeric mono">${fmt(playerValue(p,key,m))}</td>`).join('')}<td>${iconButton('全部玩家字段','player-fields','list-tree',`data-id="${p.player_id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}).join('')}`;}
function timelineView(m){if(!m.units.length)return empty('单位明细尚未归档',m.friend_count>=3?'详情会在后台自动补齐。':courtText('此局尚未达到三位朋友条件。'),isAdmin()&&m.friend_count>=3?button('补抓详情','retry-detail','refresh-cw'):'' ,'crosshair');const preferred=m.participants.find((p)=>p.registered)?.player_id??m.participants[0].player_id;if(S.selectedPlayer!=='*'&&!m.participants.some((p)=>p.player_id===S.selectedPlayer))S.selectedPlayer=preferred;const units=m.units.filter((u)=>(S.selectedPlayer==='*'||u.player_id===S.selectedPlayer)&&(!S.unitSearch||`${unitName(u.catalogue,u.unit_id)} ${u.unit_id} ${u.net_id}`.toLowerCase().includes(S.unitSearch.toLowerCase())));const start=m.detail?.data?.StartTime??(m.end_time-m.duration);const total=m.duration||1;return `<div class="timeline-toolbar"><select id="timeline-player" aria-label="玩家"><option value="*" ${S.selectedPlayer==='*'?'selected':''}>全部玩家</option>${m.participants.map((p)=>`<option value="${p.player_id}" ${p.player_id===S.selectedPlayer?'selected':''}>${esc(p.registered?`${p.member_name} / ${p.name}`:p.name)}</option>`).join('')}</select><form id="unit-search" class="flex grow"><input name="q" value="${esc(S.unitSearch)}" placeholder="单位名称 / ID / NetID" aria-label="筛选单位"><button class="icon-button" title="筛选单位" aria-label="筛选单位" type="submit">${icon('search')}</button></form><span class="muted small-text">${units.length} 个实例</span></div><div class="table-wrap"><div class="unit-timeline"><div class="timeline-ruler"><span>单位 / 实例 NetID</span><div class="ruler-labels">${[0,.25,.5,.75,1].map((r)=>`<span>${duration(r*total)}</span>`).join('')}</div><span class="numeric">伤害 / 击杀</span></div>${units.map((u)=>{const spawn=u.spawn_time===null?null:Math.max(0,Math.min(total,u.spawn_time-start));const end=u.death_time===null?total:Math.max(0,Math.min(total,u.death_time-start));const left=spawn===null?0:100*spawn/total;const width=spawn===null?0:Math.max(.25,100*(end-spawn)/total);return `<div class="timeline-row"><div><div class="unit-name" title="${esc(unitName(u.catalogue,u.unit_id))}">${esc(unitName(u.catalogue,u.unit_id))}</div><div class="table-sub mono">${u.net_id} · ${u.refunded?'已退款':u.death_time?'已阵亡':'未记录阵亡'}</div></div><div class="timeline-bar">${spawn!==null?`<span class="timeline-life ${u.refunded?'refunded':u.death_time?'':'alive'}" style="left:${left}%;width:${Math.min(width,100-left)}%" title="出场 ${duration(spawn)}${u.death_time?` · 阵亡 ${duration(end)}`:''}${u.refunded?' · 退款时间未提供':''}"></span>`:''}</div><div class="timeline-stats"><span class="mono positive">${fmt(u.damage,1)}</span><span class="mono">${u.kills} K</span>${iconButton('单位实例完整数据','unit-fields','list-tree',`data-player="${u.player_id}" data-id="${u.net_id}"`)}</div></div>`;}).join('')}</div></div>`;}
function compareView(m){const p=m.participants.filter((p)=>p.team_id!==100);if(!p.length)return empty('没有可对比的玩家');if(!p.some((x)=>x.player_id===S.compareA))S.compareA=p[0].player_id;if(!p.some((x)=>x.player_id===S.compareB))S.compareB=p[1]?.player_id??p[0].player_id;const a=p.find((x)=>x.player_id===S.compareA),b=p.find((x)=>x.player_id===S.compareB);return `<div class="comparison-selectors"><select id="compare-a" aria-label="对比玩家 A">${p.map((x)=>`<option value="${x.player_id}" ${x===a?'selected':''}>${esc(x.name)}${x.registered?` / ${esc(x.member_name)}`:''}</option>`).join('')}</select><span class="muted mono">VS</span><select id="compare-b" aria-label="对比玩家 B">${p.map((x)=>`<option value="${x.player_id}" ${x===b?'selected':''}>${esc(x.name)}${x.registered?` / ${esc(x.member_name)}`:''}</option>`).join('')}</select></div>${[['destruction','摧毁分'],['losses','损失分'],['DamageDealt','伤害'],['DamageReceived','承伤'],['objectives','占点'],['TotalExp','经验'],['TotalSpawnedUnitScore','出场分'],['TotalRefundedUnitScore','退款分'],['SupplyPointsConsumedByAllies','补给队友'],['SupplyPointsConsumedFromAllies','从队友补给'],['DamageFriendlyFireDealt','友伤']].map(([key,label])=>{const va=playerValue(a,key,m),vb=playerValue(b,key,m);const max=Math.max(va||0,vb||0,1);return `<div class="comparison-row"><span class="mono numeric positive">${fmt(va)}</span><div class="track"><span style="width:${100*(va||0)/max}%"></span></div><span class="comparison-label">${label}</span><div class="track"><span style="width:${100*(vb||0)/max}%"></span></div><span class="mono cyan">${fmt(vb)}</span></div>`;}).join('')}`;}

const treeValues=new Map();let treeSequence=0;
const FIELD_NAMES={DamageDealt:'造成伤害',DamageReceived:'承受伤害',DamageFriendlyFireDealt:'造成友伤',DamageFriendlyFireReceived:'承受友伤',Destruction:'击毁数量',Losses:'损失数量',DestructionScore:'摧毁分',LossesScore:'损失分',TotalSpawnedUnitScore:'出场分数',TotalRefundedUnitScore:'退款分数',ObjectivesCaptured:'占领目标',SupplyPointsConsumed:'消耗补给',SupplyPointsConsumedByAllies:'补给队友',SupplyPointsConsumedFromAllies:'从队友补给',TotalExp:'总经验',RawExp:'原始经验',UnitData:'单位实例',TransferredUnits:'转移单位',Medals:'勋章',OptionIds:'改装 ID',SpawnTime:'出场时间',DeathTime:'阵亡时间',WasRefunded:'是否退款',KilledCount:'击杀数',TotalDamageDealt:'造成伤害',TotalDamageReceived:'承受伤害',TotalSupplyPointsConsumed:'消耗补给'};
function treeEntry(key,value){const label=FIELD_NAMES[key]?`${FIELD_NAMES[key]} · ${key}`:key;if(value&&typeof value==='object'){const id=String(++treeSequence);treeValues.set(id,value);const n=Object.keys(value).length;return `<details class="json-node" data-tree-id="${id}"><summary>${esc(label)} <span class="faint">${Array.isArray(value)?`[${n}]`:`{${n}}`}</span></summary><div class="json-children"></div></details>`;}return `<div class="json-row"><span class="json-key">${esc(label)}</span><span class="json-value">${esc(value===null?'null':String(value))}</span></div>`;}
function jsonTree(value){return `<div class="json-tree">${Object.entries(value??{}).map(([k,v])=>treeEntry(k,v)).join('')}</div>`;}
document.addEventListener('toggle',(event)=>{const el=event.target;if(!el.matches?.('details.json-node')||!el.open||el.dataset.loaded)return;el.dataset.loaded='true';const value=treeValues.get(el.dataset.treeId);$('.json-children',el).innerHTML=Object.entries(value??{}).map(([k,v])=>treeEntry(k,v)).join('');},true);
function drawActivity(daily){const canvas=$('#activity-chart');if(!canvas)return;const draw=()=>{if(!canvas.isConnected)return;const rect=canvas.getBoundingClientRect();const dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,rect.width*dpr);canvas.height=rect.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height;const plot={x:30,y:15,w:w-38,h:h-46};const records=daily.slice(-60);const max=Math.max(4,...records.map((d)=>d.matches));ctx.font='10px Segoe UI';for(let i=0;i<=4;i++){const y=plot.y+plot.h*(1-i/4);ctx.strokeStyle='#30372d';ctx.beginPath();ctx.moveTo(plot.x,y);ctx.lineTo(w-3,y);ctx.stroke();ctx.fillStyle='#84917d';ctx.fillText(String(Math.round(max*i/4)),2,y+3);}const step=plot.w/Math.max(records.length,7);records.forEach((d,i)=>{const bh=plot.h*d.matches/max;ctx.fillStyle='#8ad5ac';ctx.fillRect(plot.x+i*step+step*.22,plot.y+plot.h-bh,Math.max(2,step*.56),bh);if(i===0||i===records.length-1||records.length<12&&i%2===0){ctx.fillStyle='#8b9784';ctx.fillText(d.day.slice(5).replace('-','/'),plot.x+i*step,h-10);}});};draw();const observer=new ResizeObserver(draw);observer.observe(canvas);setTimeout(()=>{if(!canvas.isConnected)observer.disconnect();},15000);}

function modal(title,body,{wide=false}={}){const d=$('#modal');d.className=wide?'wide':'';d.innerHTML=`<header class="modal-header"><h2 id="modal-title">${esc(title)}</h2>${iconButton('关闭','close-modal','x')}</header><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();icons();}
function closeModal(){$('#modal').close();$('#modal').innerHTML='';}
function footer(label='保存'){return `<div class="form-error" role="alert"></div><div class="modal-footer">${button('取消','close-modal')}<button type="submit" class="primary">${icon('check')}${esc(label)}</button></div>`;}
function accountModal(memberId){const options=S.members.filter((m)=>m.active&&canManage(m.id));modal(courtText('登记游戏账号'),courtHtml`<label>归属朋友<select id="account-owner">${options.map((m)=>`<option value="${m.id}" ${m.id===Number(memberId??S.user.member_id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><form id="player-search" class="inline-form" style="margin-top:16px"><label>搜索玩家<input name="q" required placeholder="玩家名称 / Steam64 ID / 主页链接" autocomplete="off"></label><button type="submit">${icon('search')}查询</button></form><div id="player-search-results" class="search-results"></div><div class="divider-label">直接登记</div><form id="manual-account"><div class="form-grid"><label>Broken Arrow 玩家 ID<input name="player_id" required inputmode="numeric" pattern="[1-9][0-9]*" placeholder="游戏内数字 ID，非 Steam64"></label><label>账号备注<input name="name" maxlength="40" placeholder="可选"></label></div>${footer(courtText('登记账号'))}</form>`);}
async function profileModal(id){modal('账号生涯统计','<div class="loading-page"><span class="spinner"></span></div>',{wide:true});const p=await api(`/api/accounts/${id}/profile`);if(!p.data){modal(p.account.name,empty('账号档案尚未同步',p.account.last_error||'等待后台读取玩家档案。','','chart-column',true));return;}const stat=p.data.statInfo??{};const info=p.data.info;const modes=[['Rt','排位赛'],['Ct','休闲赛'],['Sk','遭遇战']];const pairs=[['评分',fmt(info.rating,1)],['排名',info.rank?`#${fmt(info.rank)}`:'—'],['等级',fmt(info.level)],['最近更新',time(p.updated_at)],['消耗补给',fmt(stat.supplyPtsConsumed)],['补给队友',fmt(stat.supplyPtsConsumedByAllies)],['从队友补给',fmt(stat.supplyPtsConsumedFromAllies)],['占领补给',fmt(stat.supplyCapturedCount)],['被敌占补给',fmt(stat.supplyCapturedByEnemyCount)],['占点',fmt(stat.zoneCapturedCount)],['退款单位',fmt(stat.unitsRefundedCount)],['自毁单位',fmt(stat.unitsSelfDestructionCount)],['友伤击毁',fmt(stat.unitsKilledFriendlyFireCount)],['友伤损失',fmt(stat.unitsLostFriendlyFireCount)]];modal(`${p.account.name} · 账号生涯`, `<div class="notice">${icon('info')}此处为该游戏账号的生涯累计，包含单排及未纳入法庭的对局。</div><div class="profile-modes">${modes.map(([suffix,label])=>`<div class="profile-mode"><h3>${label}</h3><strong class="mono">${fmt(stat[`fightsCount${suffix}`])}<span class="small-text muted"> 局</span></strong><div class="hint">${fmt(stat[`winCount${suffix}`]||0)} 胜 · ${pct(stat[`winCount${suffix}`],stat[`fightsCount${suffix}`])}</div><div class="hint">单位 K/D ${ratio(stat[`unitsKilledCount${suffix}`],stat[`unitsLostCount${suffix}`])}</div><div class="hint">${hours(stat[`matchDurationTimeSec${suffix}`])}</div></div>`).join('')}</div><div class="profile-pairs">${pairs.map(([k,v])=>`<div class="profile-pair"><span>${k}</span><b class="mono">${v}</b></div>`).join('')}</div><h3 class="section-space" style="margin-bottom:12px">完整档案与全部字段</h3>${jsonTree({playerData:p.data,metadata:p.metadata})}`,{wide:true});}

document.addEventListener('click',async(event)=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const action=el.dataset.action;if(READ_ONLY&&!READ_ACTIONS.has(action))return;try{switch(action){case'close-modal':closeModal();break;case'toggle-auth':S.registering=!S.registering;renderAuth();break;case'logout':await api('/api/logout',{method:'POST',body:{}});S.user=null;closeModal();renderAuth();break;case'password':modal('账号设置',`<div class="hint" style="margin-bottom:16px">${esc(S.user.username)} · ${esc(S.user.name)}</div><form id="password-form"><div class="stack"><label>当前密码<input type="password" name="old_password" required maxlength="128" autocomplete="current-password"></label><label>新密码<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><label>确认新密码<input type="password" name="confirm" required minlength="10" maxlength="128" autocomplete="new-password"></label></div>${footer('更新密码')}</form><div class="section-space">${button('退出登录','logout','log-out','danger')}</div>`);break;case'reset-password':modal(courtText('重置朋友密码'),courtHtml`<form id="reset-password-form" data-id="${el.dataset.id}"><div class="stack"><label>新密码<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><label>确认新密码<input type="password" name="confirm" required minlength="10" maxlength="128" autocomplete="new-password"></label></div><p class="hint section-space">重置后，该朋友的现有登录会话将退出。</p>${footer('重置密码')}</form>`);break;case'refresh':if(READ_ONLY){await window.COURT_READONLY_API.refresh();S.updateAvailable=false;}await route();break;case'filter-days':S.filters.days=el.dataset.value;S.page=1;await route();break;case'clear-filters':S.filters={days:'0',member:'',map:'',mode:'0',team:'',from:'',to:''};S.page=1;await route();break;case'prev-page':S.page=Math.max(1,S.page-1);await route();break;case'next-page':S.page++;await route();break;case'analytics-tab':S.analyticsTab=el.dataset.value;await route();break;case'detail-tab':S.detailTab=el.dataset.value;$('#main').innerHTML=detailView(S.currentMatch);icons();break;case'battle-mode':S.battleMode=el.dataset.value;$('#detail-content').innerHTML=detailContent(S.currentMatch);icons();break;case'back-matches':location.hash='matches';break;case'add-account':accountModal(el.dataset.id);break;case'add-member':modal(courtText('添加朋友'),courtHtml`<form id="member-form"><label>朋友称呼<input name="name" required maxlength="40" autocomplete="off"></label>${footer(courtText('添加朋友'))}</form>`);break;case'edit-member':{const m=S.members.find((x)=>x.id===Number(el.dataset.id));modal(courtText('修改朋友称呼'),courtHtml`<form id="edit-member-form" data-id="${m.id}"><label>朋友称呼<input name="name" value="${esc(m.name)}" required maxlength="40"></label>${footer()}</form>`);break;}case'invite':{el.disabled=true;const data=await api('/api/invitations',{method:'POST',body:{member_id:el.dataset.id?Number(el.dataset.id):null}});S.lastInvite=data.code;const link=`${location.origin}/#join/${data.code}`;modal(courtText('邀请朋友注册'),`<p class="muted small-text">${el.dataset.id?courtText('此邀请码会关联到已登记的朋友。'):courtText('此邀请码将创建一位新的朋友。')}</p><div class="invite-code">${esc(data.code)}</div><div class="flex wrap">${button('复制邀请码','copy-invite','copy')}${button('复制邀请链接','copy-invite-link','link')}</div><p class="hint section-space">有效期至 ${time(data.expires_at)}，仅可使用一次。</p>${['127.0.0.1','localhost'].includes(location.hostname)?courtText('<p class="hint yellow" style="margin-top:10px">当前为本机地址。朋友从其他电脑访问时，需要使用这台电脑的局域网或部署地址。</p>'):''}`);S.lastInviteLink=link;break;}case'copy-invite':await copyText(S.lastInvite);break;case'copy-invite-link':await copyText(S.lastInviteLink);break;case'bind-result':{el.disabled=true;await bindAccount(el.dataset.player,el.dataset.name);break;}case'profile':await profileModal(el.dataset.id);break;case'reassign':{const account=S.members.flatMap((m)=>m.accounts).find((a)=>a.id===Number(el.dataset.id));modal('调整账号归属',courtHtml`<form id="reassign-form" data-id="${account.id}"><p class="small-text muted" style="margin-bottom:16px">${esc(account.name)} · #${account.player_id}</p><label>归属朋友<select name="member_id">${S.members.map((m)=>`<option value="${m.id}" ${m.id===account.member_id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>${footer('调整并重算')}</form>`);break;}case'sync-now':case'sync-full':{el.disabled=true;const result=await api('/api/sync/run',{method:'POST',body:{kind:action==='sync-full'?'full':'incremental'}});toast(result.queued?'任务已排队':'后台同步已开始');await route({quiet:true});break;}case'fetch-match':modal(courtText('按 ID 补抓历史对局'),`<form id="fetch-match-form"><label>对局 ID 或 BATrace 链接<input name="reference" required maxlength="300" autocomplete="off" placeholder="例如 6438487 或单场详情链接"></label><p class="hint section-space">${esc(courtText('详情仍可访问的历史对局可以直接归档；不足三位朋友的记录仅作为候选保存。'))}</p>${footer('抓取并归档')}</form>`);break;case'import':modal(courtText('导入历史档案'),courtHtml`<form id="import-form"><div class="stack"><label>JSON / HTML 文件<input name="file" type="file" accept=".json,.html,.htm,application/json,text/html"></label><label>或粘贴数据<textarea name="payload" rows="7" placeholder="BATrace 对局 JSON、网页 HTML，或法庭导出档案"></textarea></label><label>对局 ID（仅导入单场 HTML 时填写）<input name="match_id" inputmode="numeric" placeholder="例如 8716954"></label></div><p class="hint" style="margin-top:14px">导入会按对局 ID 去重，保留全部字段，并重新判定三人条件。登录账号与账号归属不会被覆盖。</p>${footer(courtText('导入并归档'))}</form>`);break;case'export':{const data=await api('/api/export');download(JSON.stringify(data,null,2),`court-export-${new Date().toISOString().slice(0,10)}.json`,'application/json');break;}case'backup':{el.disabled=true;const data=await api('/api/backup',{method:'POST',body:{},blob:true});download(data,`court-backup-${new Date().toISOString().slice(0,10)}.sqlite`);toast(courtText('数据库备份已生成'));break;}case'retry-detail':await api(`/api/matches/${S.currentMatch.id}/retry`,{method:'POST',body:{}});toast('已安排补抓详情');break;case'download-match':download(JSON.stringify({format:'broken-arrow-court-v1',matches:[{id:S.currentMatch.id,raw:S.currentMatch.raw,detail:S.currentMatch.detail}]},null,2),`match-${S.currentMatch.id}.json`,'application/json');break;case'player-fields':{const p=S.currentMatch.participants.find((p)=>p.player_id===el.dataset.id);modal(`${p.name} · 全部字段`,jsonTree(p.raw),{wide:true});break;}case'unit-fields':{const u=S.currentMatch.units.find((u)=>u.net_id===el.dataset.id&&u.player_id===el.dataset.player);modal(`${unitName(u.catalogue,u.unit_id)} · NetID ${u.net_id}`,jsonTree({instance:u.raw,unitCatalogue:u.catalogue}),{wide:true});break;}}}catch(e){toast(e.message,true);}finally{if(el.isConnected)el.disabled=false;}});
async function bindAccount(playerId,name){const memberId=Number($('#account-owner').value);await api('/api/accounts',{method:'POST',body:{member_id:memberId,player_id:playerId,name:name||`#${playerId}`}});closeModal();toast('账号已登记，正在安排历史同步');await route({quiet:true});}
document.addEventListener('submit',async(event)=>{const form=event.target;if(!form.id)return;if(READ_ONLY&&!['match-search','unit-search'].includes(form.id)){event.preventDefault();return;}event.preventDefault();const submit=$('button[type=submit]',form);const error=$('.form-error',form);if(error)error.textContent='';if(submit)submit.disabled=true;const f=new FormData(form);try{switch(form.id){case'auth-form':{const register=f.get('register')==='true';if(register&&f.get('password')!==f.get('confirm'))throw new Error('两次输入的密码不一致');await api(register?'/api/register':'/api/login',{method:'POST',body:{username:f.get('username'),password:f.get('password'),name:f.get('name'),invite:f.get('invite')}});const session=await api('/api/session');S.user=session.user;S.setup=false;location.hash='dashboard';await route();break;}case'password-form':if(f.get('password')!==f.get('confirm'))throw new Error('两次输入的密码不一致');await api('/api/password',{method:'POST',body:{old_password:f.get('old_password'),password:f.get('password')}});S.user=(await api('/api/session')).user;closeModal();toast('密码已更新');break;case'reset-password-form':if(f.get('password')!==f.get('confirm'))throw new Error('两次输入的密码不一致');await api(`/api/users/${form.dataset.id}/password`,{method:'POST',body:{password:f.get('password')}});closeModal();toast(courtText('朋友密码已重置'));break;case'member-form':await api('/api/members',{method:'POST',body:{name:f.get('name')}});closeModal();toast(courtText('朋友已添加'));await route({quiet:true});break;case'edit-member-form':await api(`/api/members/${form.dataset.id}`,{method:'PATCH',body:{name:f.get('name')}});closeModal();toast('称呼已更新');await route({quiet:true});break;case'player-search':{const target=$('#player-search-results');target.innerHTML='<div class="empty compact"><span class="spinner"></span><p>正在查询玩家…</p></div>';const data=await api(`/api/players/search?q=${encodeURIComponent(f.get('q'))}`);target.innerHTML=data.players.length?data.players.map((p)=>`<button type="button" class="search-result" data-action="bind-result" data-player="${esc(p.id)}" data-name="${esc(String(p.name??`#${p.id}`).slice(0,40))}" ${p.registered?'disabled':''}><span class="grow"><strong>${esc(p.name)}</strong><small>BA #${p.id} · Steam ${esc(p.steam_id??p.steamId??'—')} · 评分 ${fmt(p.rating)}</small>${p.registered?`<small>已归属 ${esc(p.registered.member_name)}</small>`:''}</span>${icon(p.registered?'check':'plus')}</button>`).join(''):empty('没有找到玩家','可以使用游戏内数字 ID 直接登记。','','search',true);icons();break;}case'manual-account':await bindAccount(f.get('player_id'),f.get('name'));break;case'reassign-form':await api(`/api/accounts/${form.dataset.id}`,{method:'PATCH',body:{member_id:Number(f.get('member_id'))}});closeModal();toast('归属已调整，开黑统计已重算');await route({quiet:true});break;case'match-search':S.query=String(f.get('q')??'');S.page=1;await route();break;case'unit-search':S.unitSearch=String(f.get('q')??'');$('#detail-content').innerHTML=timelineView(S.currentMatch);icons();break;case'sync-settings':await api('/api/settings',{method:'PATCH',body:{sync_enabled:f.get('enabled')==='on',sync_minutes:Number(f.get('minutes')),request_delay_ms:Number(f.get('delay'))}});toast('同步设置已保存');await route({quiet:true});break;case'fetch-match-form':{const r=await api('/api/import/match',{method:'POST',body:{reference:f.get('reference')}});closeModal();toast(courtHtml`对局 #${r.id} 已归档，${r.friend_count>=3?'符合开黑条件':courtText('不足三位朋友，仅保存为候选')}`);await route({quiet:true});break;}case'import-form':{let payload=String(f.get('payload')??'');const file=f.get('file');if(file&&file.size){if(file.size>25*1048576)throw new Error('单次文件不能超过 25 MB');payload=await file.text();}if(!payload.trim())throw new Error('请选择文件或粘贴数据');const r=await api('/api/import',{method:'POST',body:{payload,match_id:f.get('match_id')}});closeModal();toast(courtHtml`已新增 ${r.added} 局，更新 ${r.changed} 局，导入 ${r.details} 份完整详情`);await route({quiet:true});break;}}}catch(e){if(error)error.textContent=e.message;else{toast(e.message,true);if(form.id==='player-search')$('#player-search-results').innerHTML=`<p class="hint negative">${esc(e.message)}</p>`;}}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',async(event)=>{const el=event.target;try{if(el.dataset.filter){S.filters[el.dataset.filter]=el.value;S.page=1;await route();}else if(el.id==='candidate-toggle'){S.scope=el.checked?'all':'qualified';S.page=1;await route();}else if(el.dataset.memberActive){const value=el.checked;await api(`/api/members/${el.dataset.memberActive}`,{method:'PATCH',body:{active:value}});toast(value?courtText('朋友已恢复，统计已重算'):courtText('朋友已停用，统计已重算'));await route({quiet:true});}else if(el.dataset.accountActive){const value=el.checked;await api(`/api/accounts/${el.dataset.accountActive}`,{method:'PATCH',body:{active:value}});toast(value?'账号已恢复跟踪':'账号已停止跟踪');await route({quiet:true});}else if(el.id==='timeline-player'){S.selectedPlayer=el.value;$('#detail-content').innerHTML=timelineView(S.currentMatch);icons();}else if(el.id==='compare-a'||el.id==='compare-b'){S[el.id==='compare-a'?'compareA':'compareB']=el.value;$('#detail-content').innerHTML=compareView(S.currentMatch);icons();}}catch(e){if(el.type==='checkbox')el.checked=!el.checked;toast(e.message,true);}});
async function copyText(text){await navigator.clipboard.writeText(text);toast('已复制');}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type:type||'application/octet-stream'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
window.addEventListener('hashchange',()=>{S.detailTab='summary';S.selectedPlayer='';S.unitSearch='';S.page=1;if(location.hash.startsWith('#join/')&&!S.user){S.invite=decodeURIComponent(location.hash.slice(6));S.registering=true;renderAuth();return;}route();});
$('#modal').addEventListener('click',(e)=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
setInterval(async()=>{if(READ_ONLY)return;if(!S.user||document.hidden)return;try{S.sync=await api('/api/sync/status');if((S.sync.settings.court_mode===true)!==isCourtMode()&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){await route();return;}updateSyncIndicator();if(S.route==='sync'&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){const main=$('#main');const y=window.scrollY;main.innerHTML=syncView();icons();window.scrollTo(0,y);}}catch{}},10000);
if(READ_ONLY)setInterval(async()=>{if(document.hidden)return;try{if(await window.COURT_READONLY_API.hasUpdate()){if(!S.updateAvailable)toast('有新的对局数据，点击刷新加载');S.updateAvailable=true;updateSyncIndicator();}}catch{}},60000);
const {courtPanel,courtView}=createCourt({S,esc,icon,fmt,empty});
const {friendView,deepAnalytics,participantDeck}=createAnalysis({S,esc,icon,fmt,pct,ratio,delta,signedClass,badge,empty,kpi,heading,filterBar,time,unitName,canManage,button,footer,modal,toast,api,closeModal,route,icons,$,courtPanel});
const {performanceTabs,detailPerformance,supplyView}=createPerformance({S,esc,icon,fmt,empty});
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action="performance-mode"]');if(!el)return;
  if(!['battle','economy','supply'].includes(el.dataset.value))return;
  S.performanceMode=el.dataset.value;try{await route();}catch(error){toast(error.message,true);}
});
document.addEventListener('change',async event=>{
  const el=event.target;if(!['combo-min','supply-min','court-min'].includes(el.id))return;
  const key=el.id==='combo-min'?'comboMin':el.id==='court-min'?'courtMin':'supplyMin',value=Number(el.value);
  if(!Number.isInteger(value)||value<1||value>10000){el.value=S[key];toast('最低局数须为 1 至 10000 的整数',true);return;}
  S[key]=value;try{await route();}catch(error){toast(error.message,true);}
});
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action="toggle-court-mode"]');if(!el||!isAdmin()||S.courtChanging)return;
  S.courtChanging=true;el.disabled=true;
  try{const enabled=!isCourtMode();await api('/api/settings',{method:'PATCH',body:{court_mode:enabled}});await route();toast(enabled?'现在开庭，法庭界面已启用':'已经休庭，已恢复常规界面');}
  catch(error){toast(error.message,true);}finally{S.courtChanging=false;if(el.isConnected)el.disabled=false;}
});
installTableSorting();
init();
